function lastResetHTML(compact=false){return `<div class="${compact?'tip-last':'reset-history'}"><span title="${esc(t.lastResetHint)}">${t.lastReset}</span><span>${t.notProvided}</span></div>`;}
function resetsHTML(resets,stale=false){
  return `<section class="banked-resets"><div class="banked-heading"><span class="banked-title">${t.bankedResets}<strong class="banked-count" data-stale="${stale?'yes':'no'}">${resets?resets.available:'—'}</strong></span><a class="usage-button" href="${usageURL}" target="_blank" rel="noreferrer noopener" title="${esc(t.resetHint)}">${t.openUsage}${svg('arrow')}</a></div>${!resets?`<p class="banked-note">${t.resetUnknown}</p>`:resets.available===0?`<p class="banked-note">${t.noResets}</p>`:`${stale?`<p class="banked-note">${t.stale}</p>`:''}${resetCards(resets)}`}${lastResetHTML()}<p class="banked-note reset-route">${t.usageFallback}</p><p class="banked-note reset-history-hint">${t.historyRoute}</p></section>`;
}
function tooltipHTML(state={}){
  const usage=state.usage,info=globalThis.LimitLiveCore.badge(state);
  return `<div class="tip-heading"><strong>Work / Codex</strong><span>${esc(usage?.plan||'')}</span></div>${usage?usage.windows.map(w=>`<section class="tip-window"><div class="tip-line"><span>${esc(label(w))}</span><strong>${esc(percent(w.remaining))} <small>${t.remaining}</small></strong></div><div class="tip-reset"><span>${t.resetsIn}</span><strong>${esc(countdown(w.resetAt)||'—')}</strong></div>${w.resetAt?`<div class="tip-date">${timeHTML(w.resetAt)}</div>`:''}</section>`).join(''):`<p class="tip-empty">${esc(t[state.status]||t.empty)}</p>`}${usage?`<section class="tip-resets"><div class="tip-banked"><span>${t.bankedResets}</span><strong>${usage.resets?usage.resets.available:'—'}</strong></div>${!usage.resets?`<p class="tip-note">${t.resetUnknown}</p>`:usage.resets.available>0?resetCards(usage.resets,true):''}${lastResetHTML(true)}</section>`:''}${state.error?`<p class="tip-empty">${esc(state.error)}</p>`:''}<div class="tip-footer" data-stale="${info.stale?'yes':'no'}"><span>${esc(usage?(info.stale?t.stale:t.fresh):t[state.status]||t.empty)}</span><time>${state.updatedAt?esc(t.checked+' '+new Date(state.updatedAt).toLocaleTimeString(language,{hour:'2-digit',minute:'2-digit'})):''}</time></div>`;
}
