function setControls(root,cfg){
  for(const key of ['language','theme','position','decimals','fontWeight','interval','ringWidth','numberScale','backgroundOpacity','tooltipDelay','tooltipFontSize','tooltipWidth']){const node=root.getElementById(key);if(node&&root.activeElement!==node)node.value=String(key==='numberScale'?Math.round(cfg.numberScale*100):cfg[key]);}
  for(const key of toggles){const node=root.getElementById(key);if(node)node.checked=cfg[key];}
  const colors=effectiveColors(cfg);for(const key of globalThis.LimitLiveCore.COLOR_KEYS){const picker=root.getElementById('color_'+key),hex=root.getElementById('hex_'+key);if(picker)picker.style.setProperty('--swatch',colors[key]);if(hex&&root.activeElement!==hex)hex.value=colors[key];}
  for(const mode of ['Panel','Compact','Icon'])root.getElementById('mode'+mode)?.setAttribute('aria-pressed',String(mode==='Icon'?cfg.hidden:mode==='Compact'?!cfg.hidden&&cfg.collapsed:!cfg.hidden&&!cfg.collapsed));
}
globalThis.LimitLiveUI={orbModel,sizeControl,colorSamples,effectiveColors,resetsHTML,tooltipHTML,numericControls,toggles,t,get ru(){return ru},get language(){return language},setLanguage,usageURL,esc,svg,percent,label,countdown,meters,controls,styles,setControls};
